from rest_framework.viewsets import ViewSet
from rest_framework.response import Response
from rest_framework import permissions, status
from knox.models import AuthToken
from .models import DeviceSessionMeta

class DeviceSessionMetaViewSet(ViewSet):
    permission_classes = [permissions.IsAuthenticated]

    def partial_update(self, request, pk=None):
        try:
            # Enforce that the underlying Knox token is owned by request.user
            session_meta = DeviceSessionMeta.objects.select_related('auth_token').get(
                auth_token_id=pk,
                auth_token__user=request.user
            )
        except DeviceSessionMeta.DoesNotExist:
            return Response({'error': 'Device session metadata not found'}, status=status.HTTP_404_NOT_FOUND)

        new_device_name = request.data.get('device_name')
        session_meta.device_name = new_device_name
        session_meta.save(update_fields=['device_name'])
        return Response({'status': 'updated', 'device_name': session_meta.device_name})
